(function () {
  const INK = '#12301a';
  DD.defineEntity('pickle', {
    spawn: t => ({ x: t.x + 2, y: t.y + 1, w: 12, h: 15, vx: 0, vy: 0, dir: -1, st: 0, tm: 30 + (t.tx * 7) % 40, n: 0, an: 0, home: t.x + 8 }),
    update(e, G) {
      e.an++;
      const solidAt = (px, py) => { const tx = Math.floor(px / 16), ty = Math.floor(py / 16); for (let k = 0; k < 5; k++) if (DD.T(tx, ty + k)) return true; return false; };
      if (e.st === 0) {   // resting: turn toward Dot when close
        const dx = DD.cx(G.pl) - DD.cx(e);
        if (Math.abs(dx) < 150 && Math.abs(G.pl.y - e.y) < 90) e.dir = dx < 0 ? -1 : 1;
        const far = DD.cx(e) - e.home; if (Math.abs(far) > 56) e.dir = far > 0 ? -1 : 1;   // it stays near its patch
        if (--e.tm <= 0) { e.st = 1; e.tm = 28; }
      } else if (e.st === 1) {   // crouch: the telegraph (it squashes and its eyes go wide)
        if (--e.tm <= 0) {
          if (!solidAt(DD.cx(e) + e.dir * 36, e.y + e.h + 2)) e.dir = -e.dir;   // never hop off an edge
          e.st = 2; e.vy = -5.4; e.vx = e.dir * 1.25; DD.dust(DD.cx(e), e.y + e.h, 3, 4, '#8fd45a');
        }
      } else {
        if (DD.moveX(e, e.vx, false)) e.vx = 0;
        e.vy = Math.min(e.vy + 0.4, 6);
        if (DD.moveY(e, e.vy, false) && e.vy > 0) { e.st = 0; e.vx = 0; e.vy = 0; e.n++; e.tm = e.n % 2 ? 22 : 80; DD.dust(DD.cx(e), e.y + e.h, 3, 4, '#8fd45a'); }
      }
      if (e.y > DD.L.H * 16 + 64) e.dead = true;
    },
    stomp(e) { e.dead = true; DD.addGot(2, DD.cx(e), e.y); DD.dust(DD.cx(e), e.y + e.h, 6, 6, '#8fd45a'); DD.SFX.stomp(); return true; },
    touch(e) { DD.hurt(DD.cx(e)); },
    draw(e, ctx) {
      const X = DD.wx(e.x + e.w / 2), Y = DD.wy(e.y + e.h); if (X < -20 || X > DD.VW + 20) return;
      const crouch = e.st === 1, air = e.st === 2, bob = e.st === 0 ? Math.sin(e.an / 9) * 0.04 : 0;
      const sy = crouch ? 0.68 : air ? 1.16 : 1 + bob, sx = crouch ? 1.2 : air ? 0.9 : 1 - bob;
      ctx.save(); ctx.translate(Math.round(X), Math.round(Y)); ctx.scale(sx * e.dir * -1, sy);
      const im = DD.IMG['w1_pickle_' + (crouch ? 1 : 0)]; if (DD.ready('w1_pickle_' + (crouch ? 1 : 0))) ctx.drawImage(im, -7, -16);   // design/sprites/w_fillpass.py
      ctx.restore();
    },
  });
})();
